with filtered as (select id, account_id, txn_type, amount, merchant, case when txn_type = 'CREDIT' then 1 else 0 end is_credit, coalesce(merchant, 'DIRECT') resolved_merchant from transactions where txn_time > to_date('2023-12-22')) select case when amount >= 3100 then 'HIGH' else 'LOW' end as amount_tier, merchant, approx_percentile(is_credit, 0.95) as is_credit_p95, count(*) as num_rows, count(*) filter (where merchant = 'Amazon') as amazon_rows, rank() over (partition by case when amount >= 3100 then 'HIGH' else 'LOW' end order by count(*) filter (where merchant = 'Amazon') desc) as amazon_rows_rank from filtered group by case when amount >= 3100 then 'HIGH' else 'LOW' end, merchant;
